void reset_security(void)
{
    settingssecurity_state_param_t security_state;
    s32             ret;

    security_state.sec_state = 0;
    security_state.password[0] = 1;
    security_state.password[1] = 2;
    security_state.password[2] = 3;
    security_state.password[3] = 4;
    ret                 = aic_md_write(MD_ID_SETTING_SECURITY,sizeof(settingssecurity_state_param_t),&security_state);

    if (ret) {
        APP_LOGI("reset_security read net cfg error 0x%x\n",ret);
        }
}


uint8_t get_security_state(void)
{
    settingssecurity_state_param_t security_state;
    s32             ret;

    ret                 = aic_md_read(MD_ID_SETTING_SECURITY,sizeof(settingssecurity_state_param_t),&security_state);

    if (ret) {
        APP_LOGI("reset_security read net cfg error 0x%x\n",ret);
        }

    if (security_state.sec_state == 1)
        return 1;

    else 
        return 0;
}


