void settings_security_app_pass_ui_event_actions(lv_event_t * e)
{
    char            security_array[2];
    lv_event_code_t event_code = lv_event_get_code(e);

    //lv_obj_t * target = lv_event_get_target(e);
    //	__inf("settings_security_app_pass_ui_event_actions 00 =%d\r\n",event_code);
    if (settings_security_pass_timer && event_code == LV_EVENT_KEY)
        return;

    switch (event_code)
    {
        case LV_EVENT_SCREEN_LOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_add_obj(lv_group_get_default(),obj);
                    lv_group_focus_obj(obj);
                    }

                }
            break;

        case LV_EVENT_SCREEN_UNLOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_remove_obj(obj);
                    }
                }
            break;

        case LV_EVENT_KEY:
            {
                uint32_t        key = lv_event_get_key(e);

                __inf("settings_security_app_pass_ui_event_actions111 LV_EVENT_KEY:%d\r\n",key);

                switch (key)
                {
                    case LV_KEY_UP:
                        break;

                    case LV_KEY_DOWN:
                        break;

                    case LV_KEY_LEFT:
                        break;

                    case LV_KEY_DEL:
                        {
                            uint8_t         index = 0;
                            lv_obj_t *      label = lv_textarea_get_label(ui_FpSettingsSecurityPassContent);

                            if (_lv_txt_get_encoded_length(lv_label_get_text(label)) == 0) {
                                if (ui_FpSettingsSelected)
                                    index = 1;

                                alv_am_win_jump_action(NULL,"settings_sec",(void *) &index);
                                }

                            lv_textarea_del_char(ui_FpSettingsSecurityPassContent);
                            label               = lv_textarea_get_label(ui_FpSettingsSecurityPassContent);

                            if (_lv_txt_get_encoded_length(lv_label_get_text(label)) == 0) {
                                lv_label_set_text(ui_FpSettingsSecurityPassReturn,"返回");
                                }
                            else {
                                lv_label_set_text(ui_FpSettingsSecurityPassReturn,"删除");
                                }

                            label               = lv_textarea_get_label(ui_FpSettingsSecurityPassContent);
                            sprintf(security_array,"%d",
                                (int) (4 - _lv_txt_get_encoded_length(lv_label_get_text(label))));
                            lv_label_set_text(ui_FpSettingsSecurityPassNumIndex,security_array);
                            }
                        break;

                    case LV_KEY_0:
                    case LV_KEY_1:
                    case LV_KEY_2:
                    case LV_KEY_3:
                    case LV_KEY_4:
                    case LV_KEY_5:
                    case LV_KEY_6:
                    case LV_KEY_7:
                    case LV_KEY_8:
                    case LV_KEY_9:
                        lv_textarea_add_char(ui_FpSettingsSecurityPassContent,key - LV_KEY_0 + 0x30);
                        lv_label_set_text(ui_FpSettingsSecurityPassReturn,"删除");
                        lv_obj_t * label = lv_textarea_get_label(ui_FpSettingsSecurityPassContent);

                        sprintf(security_array,"%d",
                            (int) (4 - _lv_txt_get_encoded_length(lv_label_get_text(label))));
                        lv_label_set_text(ui_FpSettingsSecurityPassNumIndex,security_array);
                        break;

                    case LV_KEY_ESC:
                    case LV_KEY_ENTER:
                        if (1) {
                            s32             ret;
                            settingssecurity_state_param_t security_state;

                            ret                 = aic_md_read(MD_ID_SETTING_SECURITY,
                                sizeof(settingssecurity_state_param_t),&security_state);

                            if (ret) {
                                APP_LOGI("read security cfg error 0x%x\n",ret);
                                security_state.sec_state = 0;
                                }

                            lv_label_set_text(ui_FpSettingsSecurityPassNumIndex,"4");
                            lv_label_set_text(ui_FpSettingsSecurityPassReturn,"返回");

                            if ((ui_FpSettingsSelected == 0) || (ui_FpSettingsSelected == 0x80)) // 输入旧密码
                            {
                                char *          text;

                                text                = (char *) lv_textarea_get_text(ui_FpSettingsSecurityPassContent);

                                __inf("settings_security_app_pass_ui_event_actions222:%s,=0x%x\r\n",text,
                                    ui_FpSettingsSelected);
                                uint8_t         i   = 0;

                                for (i = 0; i < 4; i++) {
                                    if ((text[i] -0x30) != security_state.password[i]) {
                                        lv_obj_clear_flag(ui_FpSettingsSecurityPassWrongHint,LV_OBJ_FLAG_HIDDEN); /// Flags					
                                        lv_textarea_set_text(ui_FpSettingsSecurityPassContent,"");

                                        //lv_label_set_text(ui_FpSettingsSecurityPassNumIndex, "4");
                                        break;
                                        }
                                    }

                                if (i >= 4) {
                                    if (ui_FpSettingsSelected == 0) {
                                        alv_am_win_jump_action(NULL,"setting_sec_en",NULL);
                                        }
                                    else if (ui_FpSettingsSelected == 0x80) {
                                        lv_textarea_set_text(ui_FpSettingsSecurityPassContent,"");
                                        ui_FpSettingsSelected = 0x81;
                                        lv_obj_add_flag(ui_FpSettingsSecurityPassOldWord,LV_OBJ_FLAG_HIDDEN); /// Flags
                                        lv_obj_add_flag(ui_FpSettingsSecurityPassCheckNewWord,LV_OBJ_FLAG_HIDDEN); /// Flags
                                        lv_obj_clear_flag(ui_FpSettingsSecurityPassNewWord,LV_OBJ_FLAG_HIDDEN); /// Flags
                                        }
                                    }
                                else 
                                    settings_security_pass_timer_start(ui_FpSettingsSelected);

                                }
                            else if (ui_FpSettingsSelected == 0x81) {

                                char *          text;

                                text                = (char *) lv_textarea_get_text(ui_FpSettingsSecurityPassContent);

                                for (uint8_t i = 0; i < 4; i++)
                                    password_temp[i] = text[i] -0x30;

                                lv_textarea_set_text(ui_FpSettingsSecurityPassContent,"");
                                ui_FpSettingsSelected = 0x82;
                                lv_obj_add_flag(ui_FpSettingsSecurityPassOldWord,LV_OBJ_FLAG_HIDDEN); /// Flags
                                lv_obj_clear_flag(ui_FpSettingsSecurityPassCheckNewWord,LV_OBJ_FLAG_HIDDEN); /// Flags
                                lv_obj_add_flag(ui_FpSettingsSecurityPassNewWord,LV_OBJ_FLAG_HIDDEN); /// Flags
                                }
                            else if (ui_FpSettingsSelected == 0x82) {
                                char *          text;
                                uint8_t         i   = 0;

                                text                = (char *) lv_textarea_get_text(ui_FpSettingsSecurityPassContent);

                                for (i = 0; i < 4; i++) {
                                    if ((text[i] -0x30) != password_temp[i]) {
                                        lv_obj_clear_flag(ui_FpSettingsSecurityPassNotMatchHint,LV_OBJ_FLAG_HIDDEN);

                                        /// Flags					
                                        lv_textarea_set_text(ui_FpSettingsSecurityPassContent,"");

                                        //lv_label_set_text(ui_FpSettingsSecurityPassNumIndex, "4");
                                        for (uint8_t i = 0; i < 4; i++)
                                            password_temp[i] = 0xff;

                                        break;
                                        }
                                    }

                                if (i >= 4) {

                                    for (uint8_t i = 0; i < 4; i++)
                                        security_state.password[i] = text[i] -0x30;

                                    ret                 = aic_md_write(MD_ID_SETTING_SECURITY,
                                        sizeof(settingssecurity_state_param_t),&security_state);
                                    ui_FpSettingsSelected = 0x83;
                                    settings_security_pass_timer_start(ui_FpSettingsSelected);
                                    }
                                else 
                                    settings_security_pass_timer_start(ui_FpSettingsSelected);


                                }
                            }

                        break;

                    case LV_KEY_END:
                        alv_am_app_exit_action_all();
                        break;

                    default:
                        break;
                    }

                }
            break;

        default:
            break;
        }


}


